local B="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local M={}
for i=1,#B do M[B:sub(i,i)]=i-1 end
local function b64(d)
    d=d:gsub("[^"..B.."=]","")
    local o,i={},1
    while i<=#d do
        local a,b,c,e=d:sub(i,i),d:sub(i+1,i+1),d:sub(i+2,i+2),d:sub(i+3,i+3)
        local n1,n2=M[a] or 0,M[b] or 0
        local n3,n4=M[c],M[e]
        o[#o+1]=string.char(n1*4+math.floor(n2/16))
        if c~="=" and c~="" then o[#o+1]=string.char((n2%16)*16+math.floor((n3 or 0)/4)) end
        if e~="=" and e~="" then o[#o+1]=string.char(((n3 or 0)%4)*64+(n4 or 0)) end
        i=i+4
    end
    return table.concat(o)
end
local raw=b64(D)
local out={}
for i=1,#raw do out[i]=string.char(bit32.bxor(raw:byte(i),K[(i-1)%#K+1])) end
local fn,err=(loadstring or load)(table.concat(out))
if fn then fn() else warn("[AMValue] loi load: "..tostring(err)) end
